<script setup lang="ts">import{PhBracketsCurly}from'@phosphor-icons/vue';import{useRouter}from'vue-router';import SummaryStrip from'../components/SummaryStrip.vue';import{useAnalysis}from'../composables/useAnalysis';const a=useAnalysis(),router=useRouter();function inspect(id:string){a.selectedId.value=id;router.push({name:'map'})}</script>
<template><template v-if="a.data.value"><SummaryStrip :data="a.data.value"/><section class="files-section route-page"><header><h1>热点文件</h1><p>复杂度、变更频率与测试缺口的交集。</p></header><div class="file-table" role="table"><div class="file-row file-head" role="row"><span>路径</span><span>复杂度</span><span>变更</span><span>覆盖</span><span>作者</span></div><button v-for="file in a.data.value.hotspots" :key="file.path" class="file-row" @click="inspect(file.module)"><span><PhBracketsCurly :size="16"/><code>{{file.path}}</code></span><b>{{file.complexity}}</b><b>{{file.churn}}</b><b>{{file.coverage}}%</b><b>{{file.authors}}</b></button></div></section></template></template>
